<form method="post"><?php lf_hidden($r,$cancelDebt?'cancel_debts':($cancel?'cancel_opening':'apply')); ?><input type="hidden" name="confirmation_token" value="<?= lf_e($confirmation['confirmation_token']) ?>"><input type="hidden" name="confirmation" value="<?= $cancelDebt?'BATALKAN TUNGGAKAN LEGACY':($cancel?'BATALKAN SALDO AWAL':'TERAPKAN LEGACY') ?>"><?php if($cancel): ?><label>Alasan pembatalan<textarea name="reason" minlength="10" maxlength="1000" required></textarea></label><?php endif; ?><div class="dbt-dialog-actions"><a class="dbt-button dbt-button-outline" href="?review=<?= (int)$r['id'] ?>#review">Kembali</a><button class="dbt-button dbt-button-primary"><?= $cancelDebt?'Batalkan Tunggakan':($cancel?'Batalkan Saldo Awal':'Ya, Terapkan') ?></button></div></form></section>
